 */${content}
`
}

const replace = (rgx, string = '') => {
  return {
    name: 'replace',
    generateBundle(_, bundle) {
      Object.keys(bundle).forEach((fileName) => {
        const file = bundle[fileName];
        let code = file.code;
        code = code.replace(rgx, string);
        file.code = code;
      });
    }
  }
}

